class Solution:
    MOD = 10**9 + 7
    def solve(self, n, parent, gates, queries):
        MOD = self.MOD
        depth = [0] * n
        for i in range(1, n):
            depth[i] = depth[parent[i]] + 1
        M = []
        for r, b, w in gates:
            M.append(((r % MOD, w % MOD), (w % MOD, b % MOD)))
        def climb(v, cnt, target):
            while depth[v] > depth[target]:
                m = M[v]
                cnt = ((cnt[0]*m[0][0] + cnt[1]*m[1][0]) % MOD,
                       (cnt[0]*m[0][1] + cnt[1]*m[1][1]) % MOD)
                v = parent[v]
            return v, cnt
        ans = 0
        for a, ac, b, bc in queries:
            va, ca = (1, 0) if ac else (0, 1)
            vb, cb = (1, 0) if bc else (0, 1)
            if depth[a] < depth[b]:
                b, cb = climb(b, cb, a)
            else:
                a, ca = climb(a, ca, b)
            while a != b:
                a, ca = climb(a, ca, parent[a])
                b, cb = climb(b, cb, parent[b])
            wa = (ca[0] + ca[1]) % MOD
            wb = (cb[0] + cb[1]) % MOD
            ans ^= (wa * wb) % MOD
        return ans

