class Solution {
public:
    int solve(int n, vector<int>& parent, vector<vector<int>>& gates, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        vector<int> dep(n, 0);
        for (int i = 1; i < n; i++) dep[i] = dep[parent[i]] + 1;
        vector<array<long long,4>> M(n);
        for (int i = 0; i < n; i++) {
            long long r = gates[i][0] % MOD, b = gates[i][1] % MOD, w = gates[i][2] % MOD;
            M[i] = {r, w, w, b};
        }
        auto apply = [&](int v, array<long long,2>& c) {
            auto& m = M[v];
            long long r0 = (c[0]*m[0] + c[1]*m[2]) % MOD;
            long long r1 = (c[0]*m[1] + c[1]*m[3]) % MOD;
            c = {r0, r1};
        };
        auto climb = [&](int v, array<long long,2>& c, int t) {
            while (dep[v] > dep[t]) { apply(v, c); v = parent[v]; }
            return v;
        };
        int ans = 0;
        for (auto& q : queries) {
            int a = q[0], b = q[2];
            array<long long,2> ca = {q[1] ? 1LL : 0LL, q[1] ? 0LL : 1LL};
            array<long long,2> cb = {q[3] ? 1LL : 0LL, q[3] ? 0LL : 1LL};
            if (dep[a] < dep[b]) b = climb(b, cb, a);
            else a = climb(a, ca, b);
            while (a != b) { a = climb(a, ca, parent[a]); b = climb(b, cb, parent[b]); }
            ans ^= (int)(((ca[0]+ca[1]) % MOD) * ((cb[0]+cb[1]) % MOD) % MOD);
        }
        return ans;
    }
};

