class Solution {
    static final long MOD = 1000000007L;
    public int solve(int n, int[] parent, int[][] gates, int[][] queries) {
        int[] dep = new int[n];
        for (int i = 1; i < n; i++) dep[i] = dep[parent[i]] + 1;
        long[][] M = new long[n][4];
        for (int i = 0; i < n; i++) {
            long r = gates[i][0] % MOD, b = gates[i][1] % MOD, w = gates[i][2] % MOD;
            M[i] = new long[]{r, w, w, b};
        }
        int ans = 0;
        for (int[] q : queries) {
            int a = q[0], b = q[2];
            long[] ca = q[1] == 1 ? new long[]{1, 0} : new long[]{0, 1};
            long[] cb = q[3] == 1 ? new long[]{1, 0} : new long[]{0, 1};
            if (dep[a] < dep[b]) b = climb(b, cb, a, dep, parent, M);
            else a = climb(a, ca, b, dep, parent, M);
            while (a != b) {
                a = climb(a, ca, parent[a], dep, parent, M);
                b = climb(b, cb, parent[b], dep, parent, M);
            }
            long wa = (ca[0] + ca[1]) % MOD, wb = (cb[0] + cb[1]) % MOD;
            ans ^= (int) (wa * wb % MOD);
        }
        return ans;
    }
    private int climb(int v, long[] c, int t, int[] dep, int[] parent, long[][] M) {
        while (dep[v] > dep[t]) {
            long[] m = M[v];
            long r0 = (c[0]*m[0] + c[1]*m[2]) % MOD;
            long r1 = (c[0]*m[1] + c[1]*m[3]) % MOD;
            c[0] = r0; c[1] = r1;
            v = parent[v];
        }
        return v;
    }
}

