class Solution:
    MOD = 10**9 + 7
    def solve(self, n, parent, gates, queries):
        MOD = self.MOD
        LOG = max(1, (max(n - 1, 1)).bit_length())
        depth = [0] * n
        for i in range(1, n):
            depth[i] = depth[parent[i]] + 1
        pp = parent[:] 
        pp[0] = 0
        up = [pp]
        mt = [[]]
        for i in range(n):
            r, b, w = gates[i]
            mt[0].append((r % MOD, w % MOD, w % MOD, b % MOD))
        for k in range(1, LOG):
            pu, pm = up[k-1], mt[k-1]
            up.append([pu[pu[i]] for i in range(n)])
            cur = []
            for i in range(n):
                A, B = pm[i], pm[pu[i]]
                cur.append(((A[0]*B[0] + A[1]*B[2]) % MOD, (A[0]*B[1] + A[1]*B[3]) % MOD,
                            (A[2]*B[0] + A[3]*B[2]) % MOD, (A[2]*B[1] + A[3]*B[3]) % MOD))
            mt.append(cur)
        def lca(a, b):
            if depth[a] < depth[b]:
                a, b = b, a
            d = depth[a] - depth[b]
            for k in range(LOG):
                if d >> k & 1:
                    a = up[k][a]
            if a == b:
                return a
            for k in range(LOG - 1, -1, -1):
                if up[k][a] != up[k][b]:
                    a, b = up[k][a], up[k][b]
            return up[0][a]
        def ways(v, c, t):
            res = (1, 0) if c else (0, 1)
            d = depth[v] - depth[t]
            k = 0
            while d:
                if d & 1:
                    M = mt[k][v]
                    res = ((res[0]*M[0] + res[1]*M[2]) % MOD,
                           (res[0]*M[1] + res[1]*M[3]) % MOD)
                    v = up[k][v]
                d >>= 1
                k += 1
            return (res[0] + res[1]) % MOD
        ans = 0
        for a, ac, b, bc in queries:
            t = lca(a, b)
            ans ^= (ways(a, ac, t) * ways(b, bc, t)) % MOD
        return ans

