class Solution {
public:
    int solve(int n, vector<int>& parent, vector<vector<int>>& gates, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        int LOG = 1; while ((1 << LOG) < n) LOG++;
        vector<int> dep(n, 0);
        vector<vector<int>> up(LOG, vector<int>(n));
        vector<vector<array<long long,4>>> mt(LOG, vector<array<long long,4>>(n));
        for (int i = 0; i < n; i++) {
            up[0][i] = parent[i] == -1 ? 0 : parent[i];
            mt[0][i] = {gates[i][0] % MOD, gates[i][2] % MOD, gates[i][2] % MOD, gates[i][1] % MOD};
        }
        for (int i = 1; i < n; i++) dep[i] = dep[parent[i]] + 1;
        for (int k = 1; k < LOG; k++)
            for (int i = 0; i < n; i++) {
                up[k][i] = up[k-1][up[k-1][i]];
                auto& A = mt[k-1][i]; auto& B = mt[k-1][up[k-1][i]];
                mt[k][i] = {(A[0]*B[0] + A[1]*B[2]) % MOD, (A[0]*B[1] + A[1]*B[3]) % MOD,
                            (A[2]*B[0] + A[3]*B[2]) % MOD, (A[2]*B[1] + A[3]*B[3]) % MOD};
            }
        auto lca = [&](int a, int b) {
            if (dep[a] < dep[b]) swap(a, b);
            int d = dep[a] - dep[b];
            for (int k = 0; k < LOG; k++) if (d >> k & 1) a = up[k][a];
            if (a == b) return a;
            for (int k = LOG - 1; k >= 0; k--)
                if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
            return up[0][a];
        };
        auto ways = [&](int v, int c, int t) {
            array<long long,2> res = {c ? 1LL : 0LL, c ? 0LL : 1LL};
            int d = dep[v] - dep[t], k = 0;
            while (d) {
                if (d & 1) {
                    auto& M = mt[k][v];
                    long long r0 = (res[0]*M[0] + res[1]*M[2]) % MOD;
                    long long r1 = (res[0]*M[1] + res[1]*M[3]) % MOD;
                    res = {r0, r1};
                    v = up[k][v];
                }
                d >>= 1; k++;
            }
            return (int)((res[0] + res[1]) % MOD);
        };
        int ans = 0;
        for (auto& q : queries) {
            int t = lca(q[0], q[2]);
            ans ^= (int)((long long)ways(q[0], q[1], t) * ways(q[2], q[3], t) % MOD);
        }
        return ans;
    }
};

