class Solution {
    static final long MOD = 1000000007L;
    int LOG, n;
    int[][] up;
    long[][][] mt;
    int[] dep;
    public int solve(int n, int[] parent, int[][] gates, int[][] queries) {
        this.n = n;
        LOG = 1; while ((1 << LOG) < n) LOG++;
        dep = new int[n];
        up = new int[LOG][n];
        mt = new long[LOG][n][4];
        for (int i = 0; i < n; i++) {
            up[0][i] = parent[i] == -1 ? 0 : parent[i];
            mt[0][i] = new long[]{gates[i][0] % MOD, gates[i][2] % MOD, gates[i][2] % MOD, gates[i][1] % MOD};
        }
        for (int i = 1; i < n; i++) dep[i] = dep[parent[i]] + 1;
        for (int k = 1; k < LOG; k++)
            for (int i = 0; i < n; i++) {
                up[k][i] = up[k-1][up[k-1][i]];
                long[] A = mt[k-1][i], B = mt[k-1][up[k-1][i]];
                mt[k][i] = new long[]{(A[0]*B[0] + A[1]*B[2]) % MOD, (A[0]*B[1] + A[1]*B[3]) % MOD,
                                      (A[2]*B[0] + A[3]*B[2]) % MOD, (A[2]*B[1] + A[3]*B[3]) % MOD};
            }
        int ans = 0;
        for (int[] q : queries) {
            int t = lca(q[0], q[2]);
            ans ^= (int) (ways(q[0], q[1], t) * ways(q[2], q[3], t) % MOD);
        }
        return ans;
    }
    private int lca(int a, int b) {
        if (dep[a] < dep[b]) { int tmp = a; a = b; b = tmp; }
        int d = dep[a] - dep[b];
        for (int k = 0; k < LOG; k++) if ((d >> k & 1) == 1) a = up[k][a];
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--)
            if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
        return up[0][a];
    }
    private long ways(int v, int c, int t) {
        long r0 = c == 1 ? 1 : 0, r1 = c == 1 ? 0 : 1;
        int d = dep[v] - dep[t], k = 0;
        while (d > 0) {
            if ((d & 1) == 1) {
                long[] M = mt[k][v];
                long n0 = (r0*M[0] + r1*M[2]) % MOD;
                long n1 = (r0*M[1] + r1*M[3]) % MOD;
                r0 = n0; r1 = n1;
                v = up[k][v];
            }
            d >>= 1; k++;
        }
        return (r0 + r1) % MOD;
    }
}

